package jp.terada.midnitelogger;
import android.content.*; import android.database.*; import android.database.sqlite.*; import java.text.*; import java.util.*;
public class Database extends SQLiteOpenHelper { public Database(Context c){super(c,"midnite.db",null,1);} public void onCreate(SQLiteDatabase d){d.execSQL("CREATE TABLE log(id INTEGER PRIMARY KEY AUTOINCREMENT,ts TEXT,battery_v REAL,pv_v REAL,classic_a REAL,daily_kwh REAL,watts INTEGER,stage INTEGER,cstate INTEGER,pv_a REAL,daily_ah INTEGER,lifetime_kwh INTEGER,lifetime_ah INTEGER,batt_temp REAL,fet_temp REAL,pcb_temp REAL,float_sec INTEGER,wb_pos_ah INTEGER,wb_neg_ah INTEGER,wb_net_ah INTEGER,wb_a REAL,wb_precise_a REAL,uploaded INTEGER DEFAULT 0,retry INTEGER DEFAULT 0)");d.execSQL("CREATE TABLE event(id INTEGER PRIMARY KEY AUTOINCREMENT,ts TEXT,msg TEXT)");} public void onUpgrade(SQLiteDatabase d,int o,int n){}
 public void insert(Record r){ContentValues v=new ContentValues();v.put("ts",r.ts);v.put("battery_v",r.batteryV);v.put("pv_v",r.pvV);v.put("classic_a",r.classicA);v.put("daily_kwh",r.dailyKwh);v.put("watts",r.watts);v.put("stage",r.stage);v.put("cstate",r.state);v.put("pv_a",r.pvA);v.put("daily_ah",r.dailyAh);v.put("lifetime_kwh",r.lifetimeKwh);v.put("lifetime_ah",r.lifetimeAh);v.put("batt_temp",r.battTemp);v.put("fet_temp",r.fetTemp);v.put("pcb_temp",r.pcbTemp);v.put("float_sec",r.floatSec);v.put("wb_pos_ah",r.wbPosAh);v.put("wb_neg_ah",r.wbNegAh);v.put("wb_net_ah",r.wbNetAh);v.put("wb_a",r.wbA);v.put("wb_precise_a",r.wbPreciseA);getWritableDatabase().insert("log",null,v);}
 public void event(String m){ContentValues v=new ContentValues();v.put("ts",new SimpleDateFormat("yyyy-MM-dd HH:mm:ss",Locale.US).format(new Date()));v.put("msg",m);getWritableDatabase().insert("event",null,v);} public int pendingCount(){Cursor c=getReadableDatabase().rawQuery("SELECT COUNT(*) FROM log WHERE uploaded=0",null);c.moveToFirst();int n=c.getInt(0);c.close();return n;}
 public Record latest(){Cursor c=getReadableDatabase().rawQuery("SELECT id,ts,battery_v,pv_v,watts,stage,wb_a FROM log ORDER BY id DESC LIMIT 1",null);Record r=null;if(c.moveToFirst()){r=new Record();r.id=c.getLong(0);r.ts=c.getString(1);r.batteryV=c.getDouble(2);r.pvV=c.getDouble(3);r.watts=c.getLong(4);r.stage=c.getInt(5);r.wbA=c.getDouble(6);}c.close();return r;}
 public String recentEvents(){Cursor c=getReadableDatabase().rawQuery("SELECT ts,msg FROM event ORDER BY id DESC LIMIT 8",null);StringBuilder b=new StringBuilder("イベント履歴
");while(c.moveToNext())b.append(c.getString(0)).append("  ").append(c.getString(1)).append("
");c.close();return b.toString();}
 public Cursor pending(int limit){return getReadableDatabase().rawQuery("SELECT id,ts,battery_v,pv_v,classic_a,daily_kwh,watts,stage,cstate,pv_a,daily_ah,lifetime_kwh,lifetime_ah,batt_temp,fet_temp,pcb_temp,float_sec,wb_pos_ah,wb_neg_ah,wb_net_ah,wb_a,wb_precise_a FROM log WHERE uploaded=0 ORDER BY id LIMIT "+limit,null);} public void ack(long id){getWritableDatabase().execSQL("UPDATE log SET uploaded=1 WHERE id<=?",new Object[]{id});}
}
